import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { truncate } from 'flarum/common/utils/string';
/** With flarum/likes: someone liked one of the member's messages. */
export default class MessageLikedNotification extends Notification {
  icon() {
    return 'far fa-thumbs-up';
  }
  href() {
    const message = this.attrs.notification.subject();
    // Notifications don't include the conversation itself, only its id.
    const dialogId = message.data.relationships?.dialog?.data?.id;
    return dialogId ? app.route('dialog.message', {
      id: dialogId,
      near: message.number()
    }) : app.route('messages');
  }
  content() {
    return app.translator.trans('flarum-messages.forum.notifications.message_liked_text', {
      user: this.attrs.notification.fromUser()
    });
  }
  excerpt() {
    return truncate(this.attrs.notification.subject().contentPlain() || '', 200);
  }
}
flarum.reg.add('flarum-messages', 'forum/components/MessageLikedNotification', MessageLikedNotification);